INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('give credit where it is due', '給予應有的肯定；功勞歸於應得者', 'to acknowledge someone''s contribution appropriately', '[{"en":"Give credit where it is due — this was her idea.","zh-TW":"功勞歸於應得者——這是她的想法。"},{"en":"Good managers always give credit where it is due.","zh-TW":"好的管理者總是給予應有的肯定。"}]', 'expression'),
('hit the jackpot', '大獲全勝；成功', 'to achieve a great success or unexpected benefit', '[{"en":"The company hit the jackpot with its new app.","zh-TW":"公司憑藉新應用程式大獲全勝。"},{"en":"Hiring her was hitting the jackpot.","zh-TW":"聘用她真的是非常成功的決定。"}]', 'expression'),
('in over one''s head', '不知所措；超出能力範圍', 'in a situation that is too complex or difficult to handle', '[{"en":"Without the training he was in over his head.","zh-TW":"缺乏培訓他完全不知所措。"},{"en":"She felt in over her head managing three offices alone.","zh-TW":"獨自管理三個辦公室讓她感到超出了自己的能力範圍。"}]', 'expression'),
('jump on the bandwagon', '跟風；隨大流', 'to join a popular trend or activity', '[{"en":"Many brands jumped on the sustainability bandwagon.","zh-TW":"許多品牌跟風追求永續發展。"},{"en":"Do not just jump on the bandwagon without a real strategy.","zh-TW":"不要只是跟風而沒有真正的策略。"}]', 'expression'),
('keep the lights on', '維持基本運作；保持運轉', 'to do the minimum to keep something functioning', '[{"en":"During the restructuring we just need to keep the lights on.","zh-TW":"在重組期間我們只需要維持基本運作。"},{"en":"The skeleton crew kept the lights on during the holiday.","zh-TW":"最少員工在假期期間維持了基本運轉。"}]', 'expression'),
('light at the end of the tunnel', '看到希望；苦盡甘來', 'signs that a long period of difficulty is ending', '[{"en":"After months of losses we finally see light at the end of the tunnel.","zh-TW":"經過幾個月的虧損我們終於看到了希望。"},{"en":"The new contract represents light at the end of the tunnel.","zh-TW":"新合同代表著苦盡甘來的希望。"}]', 'expression'),
('make a case for', '為…提出論據；力主', 'to argue in favor of something with evidence', '[{"en":"She made a strong case for increasing the marketing budget.","zh-TW":"她為增加行銷預算提出了有力論據。"},{"en":"Can you make a case for expanding to Asia?","zh-TW":"你能為拓展至亞洲提出論據嗎？"}]', 'expression'),
('make waves', '引起轟動；製造影響', 'to cause a significant impact or controversy', '[{"en":"Her bold strategy made waves in the industry.","zh-TW":"她大膽的策略在業界引起了轟動。"},{"en":"The new startup is already making waves.","zh-TW":"這家新創公司已經引起了廣泛關注。"}]', 'expression'),
('miss the mark', '未達目標；落空', 'to fail to achieve the intended result or standard', '[{"en":"The campaign missed the mark with the target audience.","zh-TW":"這次活動未能打動目標受眾。"},{"en":"His presentation missed the mark in terms of data.","zh-TW":"他的簡報在數據方面未達標準。"}]', 'expression'),
('on the cutting edge', '處於前沿；最先進的', 'at the most advanced or innovative level', '[{"en":"Our lab is on the cutting edge of AI research.","zh-TW":"我們的實驗室處於人工智慧研究的前沿。"},{"en":"They invest heavily to stay on the cutting edge.","zh-TW":"他們大量投資以保持在前沿地位。"}]', 'expression'),
('on the fence', '舉棋不定；態度模糊', 'undecided or neutral about an issue', '[{"en":"She is still on the fence about accepting the offer.","zh-TW":"她對是否接受邀請仍舉棋不定。"},{"en":"Many investors are on the fence given current uncertainty.","zh-TW":"鑑於當前不確定性許多投資者態度模糊。"}]', 'expression'),
('pick up the slack', '彌補不足；代勞', 'to do more work to compensate for others'' lack of effort', '[{"en":"The senior team picked up the slack during onboarding.","zh-TW":"在入職期間資深團隊彌補了工作不足。"},{"en":"Everyone had to pick up the slack after the layoffs.","zh-TW":"裁員後每個人都要彌補人手不足。"}]', 'expression'),
('pull one''s weight', '盡自己的本分；充分貢獻', 'to do one''s fair share of work in a group', '[{"en":"Every team member must pull their weight.","zh-TW":"每位團隊成員都必須盡自己的本分。"},{"en":"He was let go for not pulling his weight.","zh-TW":"他因為沒有充分貢獻而被解僱。"}]', 'expression'),
('put on the same footing', '建立平等地位；使處於同等條件', 'to make things or people equal in status or treatment', '[{"en":"The new policy puts all employees on the same footing.","zh-TW":"新政策使所有員工處於平等地位。"},{"en":"We put the two proposals on the same footing for comparison.","zh-TW":"我們將兩份提案放在同等條件下比較。"}]', 'expression'),
('separate the wheat from the chaff', '去蕪存菁；分辨優劣', 'to distinguish the good from the bad or valuable from worthless', '[{"en":"The rigorous interview separates the wheat from the chaff.","zh-TW":"嚴格的面試去蕪存菁。"},{"en":"Market competition helps separate the wheat from the chaff.","zh-TW":"市場競爭有助於分辨優劣企業。"}]', 'expression'),
('strike while the iron is hot', '趁熱打鐵；把握時機', 'to take advantage of an opportunity at the right moment', '[{"en":"Customer interest is high — strike while the iron is hot.","zh-TW":"客戶興趣高漲——要趁熱打鐵。"},{"en":"She struck while the iron was hot and closed the deal.","zh-TW":"她趁熱打鐵完成了交易。"}]', 'expression'),
('in keeping with', '符合；與…一致', 'consistent with or appropriate to', '[{"en":"The decision was in keeping with company values.","zh-TW":"這個決定符合公司價值觀。"},{"en":"In keeping with tradition the annual award was presented.","zh-TW":"依照傳統頒發了年度獎項。"}]', 'prepositional phrase'),
('with the exception of', '除了…之外', 'excluding a particular person or thing', '[{"en":"All branches are profitable with the exception of the newest one.","zh-TW":"除最新分店外所有分店都盈利。"},{"en":"With the exception of a few issues the rollout was smooth.","zh-TW":"除了幾個問題外推出很順利。"}]', 'prepositional phrase'),
('to the extent that', '在…的程度上；以致於', 'to the degree that something is true or happens', '[{"en":"To the extent that demand allows we will increase production.","zh-TW":"在需求允許的程度上我們將增加生產。"},{"en":"Cuts were made to the extent that performance suffered.","zh-TW":"削減達到了影響績效的程度。"}]', 'prepositional phrase'),
('in the event of', '萬一；如果發生', 'if something happens, especially something undesirable', '[{"en":"In the event of a system failure please contact support.","zh-TW":"萬一系統故障請聯繫支援。"},{"en":"In the event of non-payment legal action will be taken.","zh-TW":"萬一未付款將採取法律行動。"}]', 'prepositional phrase'),
('on the strength of', '憑借；依據', 'because of evidence or a quality that supports action', '[{"en":"She was hired on the strength of her portfolio.","zh-TW":"她憑借作品集被錄用了。"},{"en":"On the strength of our track record we won the bid.","zh-TW":"憑借我們的業績記錄我們贏得了競標。"}]', 'prepositional phrase'),
('in the face of', '面對；不顧', 'when confronted by or despite a challenging situation', '[{"en":"In the face of competition we maintained market share.","zh-TW":"面對競爭我們維持了市場份額。"},{"en":"She succeeded in the face of significant obstacles.","zh-TW":"她面對重大障礙依然成功了。"}]', 'prepositional phrase'),
('as a matter of', '作為…問題；在…方面', 'considered as a question of or relating to a specific area', '[{"en":"As a matter of policy all decisions require documentation.","zh-TW":"作為政策問題所有決策都需要記錄在案。"},{"en":"She reviews every proposal as a matter of routine.","zh-TW":"她作為慣例審查每份提案。"}]', 'prepositional phrase'),
('in partnership with', '與…合作；攜手', 'working together with another party', '[{"en":"We launched the product in partnership with a major retailer.","zh-TW":"我們與一家大型零售商合作推出了這款產品。"},{"en":"In partnership with the city we are building a tech hub.","zh-TW":"我們與市政府攜手建設科技中心。"}]', 'prepositional phrase'),
('ahead of time', '提前；事先', 'before the scheduled or expected time', '[{"en":"Please submit the report ahead of time if possible.","zh-TW":"如有可能請提前提交報告。"},{"en":"They completed the installation ahead of time.","zh-TW":"他們提前完成了安裝。"}]', 'prepositional phrase'),
('at your convenience', '在您方便的時候；按您的時間', 'whenever it suits the other person''s schedule', '[{"en":"Please reply at your convenience.","zh-TW":"請在您方便的時候回覆。"},{"en":"We can schedule the demo at your convenience.","zh-TW":"我們可以在您方便的時候安排演示。"}]', 'prepositional phrase'),
('under no circumstances', '在任何情況下都不；絕不', 'not in any situation; absolutely not', '[{"en":"Under no circumstances should client data be shared.","zh-TW":"在任何情況下都不得共享客戶數據。"},{"en":"Under no circumstances are employees permitted to accept gifts.","zh-TW":"員工在任何情況下都不得接受禮品。"}]', 'prepositional phrase'),
('as a consequence of', '由於；因為…的後果', 'resulting from or because of something', '[{"en":"As a consequence of the review new guidelines were issued.","zh-TW":"作為審查的後果頒布了新指引。"},{"en":"As a consequence of missing the deadline we lost the client.","zh-TW":"由於錯過截止日期我們失去了客戶。"}]', 'prepositional phrase'),
('with effect from', '自…起生效', 'beginning to apply from a specified date', '[{"en":"The new pricing is with effect from July 1.","zh-TW":"新定價自7月1日起生效。"},{"en":"With effect from next month all requests must go through the system.","zh-TW":"自下個月起所有申請必須通過系統提交。"}]', 'prepositional phrase'),
('on the condition that', '條件是；以…為前提', 'only if a specific requirement is met', '[{"en":"They approved the budget on the condition that costs are tracked.","zh-TW":"他們以追蹤成本為前提批准了預算。"},{"en":"We will proceed on the condition that the terms are revised.","zh-TW":"我們將以修訂條款為前提繼續推進。"}]', 'prepositional phrase'),
('at the initiative of', '在…的倡議下；由…發起', 'started or driven by a particular person or body', '[{"en":"The programme was launched at the initiative of the CEO.","zh-TW":"該計劃由執行長發起。"},{"en":"At the initiative of the R&D team a new lab was opened.","zh-TW":"在研發團隊的倡議下新實驗室開放了。"}]', 'prepositional phrase'),
('game changer', '改變局面的事物；革命性變化', 'something that fundamentally alters a situation or industry', '[{"en":"This technology is a real game changer for logistics.","zh-TW":"這項技術是物流業真正的革命性變化。"},{"en":"Her hire was a game changer for the team.","zh-TW":"她的加入改變了整個團隊的局面。"}]', 'business idiom'),
('thought leader', '思想領袖；行業影響者', 'a recognized authority whose ideas influence others', '[{"en":"She is a well-known thought leader in digital marketing.","zh-TW":"她是數位行銷領域公認的思想領袖。"},{"en":"Publishing articles helped him become a thought leader.","zh-TW":"發表文章幫助他成為行業思想領袖。"}]', 'business idiom'),
('paradigm shift', '典範轉移；根本性的轉變', 'a fundamental change in approach or understanding', '[{"en":"Remote work represents a paradigm shift in employment.","zh-TW":"遠端工作代表了就業模式的典範轉移。"},{"en":"The digital revolution was a paradigm shift for business.","zh-TW":"數位革命是商業模式的根本性轉變。"}]', 'business idiom'),
('pain point', '痛點；困擾點', 'a specific problem that customers or employees experience', '[{"en":"Our product directly addresses customer pain points.","zh-TW":"我們的產品直接解決客戶的痛點。"},{"en":"Understanding pain points helps develop better solutions.","zh-TW":"了解痛點有助於開發更好的解決方案。"}]', 'business idiom'),
('going concern', '持續經營；有活力的事業', 'a business that is expected to continue operating normally', '[{"en":"The auditors confirmed the company is a going concern.","zh-TW":"審計師確認公司是持續經營實體。"},{"en":"Investors look for businesses that are proven going concerns.","zh-TW":"投資者尋找持續盈利的企業。"}]', 'business idiom'),
('net net', '最終結果；總結而言', 'the final result after all factors are considered', '[{"en":"Net net the project was a success despite the delays.","zh-TW":"總結而言儘管有延誤這個專案是成功的。"},{"en":"Net net we saved more money than we spent.","zh-TW":"最終結果是我們省的錢多於花的錢。"}]', 'business idiom'),
('onboarding', '入職培訓；客戶引導', 'the process of integrating a new employee or customer', '[{"en":"A strong onboarding process reduces turnover.","zh-TW":"完善的入職培訓流程能降低員工流動率。"},{"en":"Client onboarding took three days with the new system.","zh-TW":"使用新系統客戶引導只需三天。"}]', 'business idiom'),
('pipeline', '業務管道；潛在機會', 'potential clients or opportunities being developed', '[{"en":"We have a strong pipeline heading into Q4.","zh-TW":"我們在進入第四季時有強勁的業務管道。"},{"en":"The sales team is working to fill the pipeline.","zh-TW":"銷售團隊正在努力填充業務管道。"}]', 'business idiom'),
('run rate', '年化運行率；按現行速度推算', 'the projected performance extrapolated from current results', '[{"en":"Our run rate puts us on track for record revenue.","zh-TW":"我們的運行率顯示有望實現創紀錄的收入。"},{"en":"Based on run rate we will exceed annual targets.","zh-TW":"根據運行率我們將超額完成年度目標。"}]', 'business idiom'),
('headcount', '員工人數；頭人數', 'the total number of employees in an organization', '[{"en":"Management approved increasing headcount by 10%.","zh-TW":"管理層批准將員工人數增加10%。"},{"en":"Headcount was reduced to cut costs during the downturn.","zh-TW":"在經濟下滑期間透過裁員削減了成本。"}]', 'business idiom'),
('benchmark', '基準；比較標準', 'a standard used to measure or compare performance', '[{"en":"We benchmark our prices against industry leaders.","zh-TW":"我們以行業領導者為基準比較我們的價格。"},{"en":"The project set a new benchmark for quality.","zh-TW":"這個專案為品質設定了新的基準。"}]', 'business idiom'),
('agile', '靈活的；敏捷開發的', 'responsive to change; using iterative development methods', '[{"en":"We shifted to an agile methodology for faster delivery.","zh-TW":"我們轉向敏捷方法論以加快交付速度。"},{"en":"An agile team can adapt quickly to client needs.","zh-TW":"靈活的團隊能迅速適應客戶需求。"}]', 'business idiom'),
('outsource', '外包', 'to hire external parties to perform business functions', '[{"en":"We outsource IT support to reduce overhead.","zh-TW":"我們將IT支援外包以降低開銷。"},{"en":"The company outsourced manufacturing to Southeast Asia.","zh-TW":"公司將製造業務外包至東南亞。"}]', 'business idiom'),
('return on investment', '投資回報率', 'the profit or benefit gained relative to the cost of investment', '[{"en":"The return on investment for this campaign was excellent.","zh-TW":"此次活動的投資回報率非常高。"},{"en":"We must demonstrate a strong return on investment.","zh-TW":"我們必須展示強勁的投資回報率。"}]', 'business idiom'),
('market share', '市場份額；市佔率', 'the percentage of a market controlled by a company', '[{"en":"We grew our market share by 5% last year.","zh-TW":"去年我們的市場份額增長了5%。"},{"en":"The new entrant is eating into our market share.","zh-TW":"新進入者正在蠶食我們的市場份額。"}]', 'business idiom'),
('call in', '請來；召喚；致電', 'to request someone to come, or to phone in', '[{"en":"We called in an external expert to assess the risk.","zh-TW":"我們請來了外部專家評估風險。"},{"en":"She called in a favor from her former colleague.","zh-TW":"她請了前同事幫忙。"}]', 'phrasal verb'),
('cut through', '突破；穿透；直截了當', 'to get through complexity or red tape efficiently', '[{"en":"Her concise email cut through all the confusion.","zh-TW":"她簡潔的郵件一下子消除了所有混亂。"},{"en":"We need to cut through bureaucracy to move faster.","zh-TW":"我們需要突破官僚主義才能加快進度。"}]', 'phrasal verb'),
('double up', '加倍；合用；臨時合併', 'to increase to twice the amount, or to share', '[{"en":"We doubled up on marketing to boost awareness.","zh-TW":"我們加倍了行銷投入以提高知名度。"},{"en":"The two teams doubled up to meet the deadline.","zh-TW":"兩個團隊合力趕上了截止日期。"}]', 'phrasal verb'),
('edge out', '略勝；擠掉；緩慢超越', 'to narrowly defeat or overtake a competitor', '[{"en":"We edged out our competitor on price.","zh-TW":"我們在價格上略勝競爭對手。"},{"en":"The new product edged out the leading brand.","zh-TW":"新產品悄悄超越了領先品牌。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('flesh out', '充實；補充細節', 'to add details or substance to an idea or plan', '[{"en":"Please flesh out this concept with specific examples.","zh-TW":"請用具體例子充實這個概念。"},{"en":"She fleshed out the proposal before the board meeting.","zh-TW":"她在董事會會議前充實了提案細節。"}]', 'phrasal verb'),
('free up', '釋放；騰出', 'to make time, money, or resources available', '[{"en":"Automating this process will free up staff for other work.","zh-TW":"自動化這個流程將釋放員工去做其他工作。"},{"en":"We restructured to free up capital for investment.","zh-TW":"我們重組以騰出資金進行投資。"}]', 'phrasal verb'),
('get across', '傳達；讓人理解', 'to successfully communicate a message or idea', '[{"en":"She struggled to get her point across in the meeting.","zh-TW":"她在會議中努力傳達自己的觀點。"},{"en":"Good visuals help get complex ideas across.","zh-TW":"好的視覺資料有助於傳達複雜的想法。"}]', 'phrasal verb'),
('jump in', '加入；插話；立即行動', 'to enter or participate suddenly and enthusiastically', '[{"en":"Feel free to jump in with your questions at any time.","zh-TW":"歡迎隨時插話提問。"},{"en":"She jumped in to help when the project was falling behind.","zh-TW":"當專案進度落後時她立即加入幫忙。"}]', 'phrasal verb'),
('make the most of', '充分利用；善加運用', 'to use something as effectively as possible', '[{"en":"Make the most of this networking event.","zh-TW":"好好把握這次人脈拓展活動。"},{"en":"She made the most of her international assignment.","zh-TW":"她充分利用了海外派駐的機會。"}]', 'phrasal verb'),
('narrow in on', '逐步鎖定；縮小焦點', 'to focus increasingly on a specific thing', '[{"en":"The investigators narrowed in on three suspects.","zh-TW":"調查人員逐步縮小到三名嫌疑人。"},{"en":"We narrowed in on the most cost-effective solution.","zh-TW":"我們逐步鎖定了最具成本效益的解決方案。"}]', 'phrasal verb'),
('open up', '開放；打開；拓展', 'to become available, or to expand access', '[{"en":"The new trade deal opens up the Asian market.","zh-TW":"新的貿易協議打開了亞洲市場。"},{"en":"She opened up a discussion about remote work policies.","zh-TW":"她開放了關於遠端工作政策的討論。"}]', 'phrasal verb'),
('phase in', '逐步引入；分階段實施', 'to introduce something gradually in stages', '[{"en":"The new regulations will be phased in over two years.","zh-TW":"新法規將分兩年逐步實施。"},{"en":"They phased in the software changes with minimal disruption.","zh-TW":"他們在最小干擾的情況下分階段引入了軟體變更。"}]', 'phrasal verb'),
('play up', '強調；過分渲染', 'to emphasize or exaggerate a quality or problem', '[{"en":"The sales pitch played up the product''s unique features.","zh-TW":"銷售宣傳強調了產品的獨特功能。"},{"en":"Do not play up minor issues in the negotiation.","zh-TW":"談判中不要過分渲染小問題。"}]', 'phrasal verb'),
('push through', '強行推進；使通過', 'to force something to completion despite opposition', '[{"en":"The CEO pushed through the restructuring plan.","zh-TW":"執行長強行推進了重組計劃。"},{"en":"They pushed through the policy despite resistance.","zh-TW":"他們不顧阻力推進了政策實施。"}]', 'phrasal verb'),
('put through', '使接通；使承受；完成', 'to connect a call, or to subject someone to an ordeal', '[{"en":"Let me put you through to the accounts department.","zh-TW":"我幫您轉接到帳務部門。"},{"en":"New employees are put through a rigorous training programme.","zh-TW":"新員工要接受嚴格的培訓計劃。"}]', 'phrasal verb'),
('queue up', '排隊；等待', 'to stand in line or wait in order', '[{"en":"Multiple projects are queued up for approval.","zh-TW":"多個專案正在排隊等待批准。"},{"en":"Customers queued up for the limited release.","zh-TW":"顧客排隊等候限量版產品。"}]', 'phrasal verb'),
('reach an agreement', '達成協議', 'to come to a mutual understanding or deal', '[{"en":"After three rounds of talks we reached an agreement.","zh-TW":"經過三輪談判我們達成了協議。"},{"en":"Both parties reached an agreement on the payment terms.","zh-TW":"雙方就付款條款達成了協議。"}]', 'phrasal verb'),
('rebound from', '從…中反彈；恢復', 'to recover after a setback or negative event', '[{"en":"The market rebounded from last quarter''s losses.","zh-TW":"市場從上季度的虧損中反彈了。"},{"en":"The company rebounded from the crisis stronger than before.","zh-TW":"公司從危機中比以前更強壯地反彈了。"}]', 'phrasal verb'),
('reconcile with', '與…和解；核對', 'to resolve differences, or to make consistent', '[{"en":"The team needs to reconcile the budget figures.","zh-TW":"團隊需要核對預算數字。"},{"en":"They reconciled their differences after the mediation.","zh-TW":"調解後他們化解了分歧。"}]', 'phrasal verb'),
('rotate out', '輪換；調換崗位', 'to replace in a rotation system', '[{"en":"Staff are rotated out every two years for fresh perspective.","zh-TW":"員工每兩年輪換一次以帶來新視角。"},{"en":"The committee chairman is rotated out annually.","zh-TW":"委員會主席每年輪換。"}]', 'phrasal verb'),
('segment out', '細分；劃分市場', 'to divide into distinct groups for analysis or targeting', '[{"en":"We segment out customers by purchase frequency.","zh-TW":"我們按購買頻率細分客戶。"},{"en":"Please segment out the B2B data for separate analysis.","zh-TW":"請將B2B數據單獨分離出來進行分析。"}]', 'phrasal verb'),
('ship out', '運出；出貨', 'to send goods out for delivery', '[{"en":"All orders will be shipped out within 48 hours.","zh-TW":"所有訂單將在48小時內出貨。"},{"en":"We shipped out the last batch of products yesterday.","zh-TW":"我們昨天發出了最後一批產品。"}]', 'phrasal verb'),
('size up', '評估；打量', 'to assess or evaluate a person or situation', '[{"en":"She quickly sized up the competitive landscape.","zh-TW":"她迅速評估了競爭格局。"},{"en":"Before the negotiation he sized up his counterpart.","zh-TW":"談判前他仔細打量了對方。"}]', 'phrasal verb'),
('start up', '創業；啟動', 'to begin a new business or start a machine', '[{"en":"She started up her own consultancy last year.","zh-TW":"她去年創辦了自己的顧問公司。"},{"en":"The system takes two minutes to start up.","zh-TW":"系統需要兩分鐘才能啟動。"}]', 'phrasal verb'),
('streamline', '精簡；優化流程', 'to make a process more efficient by removing unnecessary steps', '[{"en":"We streamlined the approval process to save time.","zh-TW":"我們精簡了審批流程以節省時間。"},{"en":"The software helps streamline our operations.","zh-TW":"這個軟體有助於優化我們的運作。"}]', 'phrasal verb'),
('take a hit', '遭受損失；受打擊', 'to suffer a loss or negative impact', '[{"en":"Sales took a hit during the pandemic.","zh-TW":"疫情期間銷售遭受了打擊。"},{"en":"The brand took a hit after the recall.","zh-TW":"召回事件後品牌聲譽受到了損害。"}]', 'phrasal verb'),
('trim down', '削減；精簡', 'to reduce the size or number of something', '[{"en":"We trimmed down the project scope to fit the budget.","zh-TW":"我們縮減了專案範圍以符合預算。"},{"en":"The team was trimmed down after the restructure.","zh-TW":"重組後團隊規模被削減了。"}]', 'phrasal verb'),
('try out', '試用；測試', 'to test something to see if it works or is suitable', '[{"en":"We are trying out a new scheduling tool.","zh-TW":"我們正在試用新的排程工具。"},{"en":"She tried out several vendors before choosing one.","zh-TW":"她在選定供應商前試用了幾家。"}]', 'phrasal verb'),
('take a back seat', '退到幕後；讓位', 'to take a less active or prominent role', '[{"en":"After the merger the founder took a back seat.","zh-TW":"合併後創辦人退居幕後。"},{"en":"She took a back seat to let her team shine.","zh-TW":"她退到幕後讓團隊大放異彩。"}]', 'expression'),
('take the plunge', '大膽行動；鼓起勇氣', 'to decide to do something after hesitating', '[{"en":"We finally took the plunge and opened an overseas office.","zh-TW":"我們終於鼓起勇氣開設了海外辦事處。"},{"en":"She took the plunge and launched her startup.","zh-TW":"她大膽行動創辦了自己的新創公司。"}]', 'expression'),
('there is no going back', '無法回頭；不可逆', 'when a decision or action cannot be undone', '[{"en":"Once you sign the contract there is no going back.","zh-TW":"一旦簽了合同就無法回頭了。"},{"en":"There is no going back after announcing the merger.","zh-TW":"宣布合併後就無法回頭了。"}]', 'expression'),
('tip of the iceberg', '冰山一角；只是表面', 'a small visible part of a much larger problem or issue', '[{"en":"These complaints are just the tip of the iceberg.","zh-TW":"這些投訴只是冰山一角。"},{"en":"The losses revealed were the tip of the iceberg.","zh-TW":"揭露的損失只是冰山一角。"}]', 'expression'),
('turn the tide', '扭轉局勢；改變形勢', 'to reverse a difficult or losing situation', '[{"en":"The new product launch turned the tide for the company.","zh-TW":"新產品發布扭轉了公司的局勢。"},{"en":"A bold strategy can turn the tide in our favor.","zh-TW":"大膽的策略可以扭轉形勢讓我們佔優。"}]', 'expression'),
('under the radar', '低調；未被注意', 'not attracting attention or scrutiny', '[{"en":"The startup operated under the radar for two years.","zh-TW":"這家新創公司低調運作了兩年。"},{"en":"She kept the project under the radar until launch day.","zh-TW":"她在發布當天之前讓專案保持低調。"}]', 'expression'),
('wear many hats', '身兼多職；扮演多種角色', 'to perform multiple roles or responsibilities simultaneously', '[{"en":"In a startup everyone wears many hats.","zh-TW":"在新創公司每個人都要身兼多職。"},{"en":"She wears many hats as both designer and developer.","zh-TW":"她身兼設計師和開發人員多職。"}]', 'expression'),
('win-win situation', '雙贏局面', 'a situation where everyone involved benefits', '[{"en":"The deal is a win-win situation for both companies.","zh-TW":"這筆交易對兩家公司都是雙贏局面。"},{"en":"We aim to create a win-win situation with every partner.","zh-TW":"我們的目標是與每個合作夥伴創造雙贏局面。"}]', 'expression'),
('working against the clock', '與時間賽跑；趕時間', 'working under extreme time pressure to finish something', '[{"en":"We were working against the clock to meet the deadline.","zh-TW":"我們與時間賽跑趕上截止日期。"},{"en":"The engineering team worked against the clock to fix the bug.","zh-TW":"工程團隊與時間賽跑修復了漏洞。"}]', 'expression'),
('worth its weight in gold', '價值連城；非常有用', 'extremely valuable or useful', '[{"en":"A reliable vendor is worth its weight in gold.","zh-TW":"一個可靠的供應商價值連城。"},{"en":"Her experience is worth its weight in gold for the team.","zh-TW":"她的經驗對團隊來說非常寶貴。"}]', 'expression'),
('you reap what you sow', '一分耕耘一分收穫', 'results reflect the effort or actions invested', '[{"en":"Our growth is no surprise — you reap what you sow.","zh-TW":"我們的增長並不令人驚訝——一分耕耘一分收穫。"},{"en":"Invest in your team and you reap what you sow.","zh-TW":"投資你的團隊你就會得到回報。"}]', 'expression'),
('zero tolerance', '零容忍', 'a policy of strict punishment for any violation, no exceptions', '[{"en":"We have zero tolerance for workplace harassment.","zh-TW":"我們對職場騷擾採取零容忍態度。"},{"en":"The company maintains zero tolerance for data breaches.","zh-TW":"公司對數據洩露保持零容忍。"}]', 'expression'),
('food for thought', '值得深思；引人思考的觀點', 'something that stimulates serious consideration', '[{"en":"The report gives us a lot of food for thought.","zh-TW":"這份報告給我們很多值得深思的觀點。"},{"en":"Her questions provided food for thought.","zh-TW":"她的問題引人深思。"}]', 'expression'),
('get the wrong end of the stick', '誤解；理解錯誤', 'to misunderstand a situation completely', '[{"en":"He got the wrong end of the stick about the promotion.","zh-TW":"他誤解了有關晉升的情況。"},{"en":"She got the wrong end of the stick from my email.","zh-TW":"她從我的郵件中得出了錯誤的理解。"}]', 'expression'),
('keep one''s cards close to one''s chest', '守口如瓶；不透露計劃', 'to keep plans or intentions secret', '[{"en":"During negotiations she kept her cards close to her chest.","zh-TW":"在談判期間她守口如瓶不透露底牌。"},{"en":"Keep your cards close to your chest until the right moment.","zh-TW":"在適當時機到來之前不要透露你的計劃。"}]', 'expression'),
('let the dust settle', '讓塵埃落定；等局勢穩定', 'to wait for a confusing or stressful situation to calm down', '[{"en":"Let the dust settle before announcing any changes.","zh-TW":"在宣布任何變更之前讓塵埃先落定。"},{"en":"After the merger we let the dust settle for a month.","zh-TW":"合併後我們等了一個月讓局勢穩定。"}]', 'expression'),
('in proportion with', '與…成比例；相稱', 'in a balanced relationship with something else', '[{"en":"Pay should increase in proportion with responsibility.","zh-TW":"薪資應與責任相稱地增加。"},{"en":"Risk is in proportion with the potential return.","zh-TW":"風險與潛在回報相稱。"}]', 'prepositional phrase'),
('under pressure', '在壓力下；被迫', 'experiencing stress or being forced to do something', '[{"en":"She performs well even under pressure.","zh-TW":"她即使在壓力下也表現良好。"},{"en":"Under pressure the team delivered an excellent result.","zh-TW":"在壓力下團隊交出了優秀的成果。"}]', 'prepositional phrase'),
('in contrast with', '與…對比；相比之下', 'when compared against something different', '[{"en":"In contrast with last year this quarter shows growth.","zh-TW":"與去年相比本季呈現出增長。"},{"en":"In contrast with competitors we offer free support.","zh-TW":"與競爭對手相比我們提供免費支援。"}]', 'prepositional phrase'),
('under review', '正在審查中', 'currently being examined or assessed', '[{"en":"The pricing model is currently under review.","zh-TW":"定價模型目前正在審查中。"},{"en":"All submitted proposals are under review.","zh-TW":"所有提交的提案都在審查中。"}]', 'prepositional phrase'),
('on reflection', '經過反思；仔細考慮後', 'after thinking carefully about something', '[{"en":"On reflection we decided to revise the proposal.","zh-TW":"經過反思我們決定修改提案。"},{"en":"On reflection her decision proved to be correct.","zh-TW":"仔細考慮後她的決定被證明是正確的。"}]', 'prepositional phrase'),
('in default of', '在缺乏…的情況下；因未履行', 'in the absence of, or because of failure to fulfill', '[{"en":"In default of payment the contract will be terminated.","zh-TW":"在未付款的情況下合同將被終止。"},{"en":"In default of a response we will proceed unilaterally.","zh-TW":"在缺乏回覆的情況下我們將單方面推進。"}]', 'prepositional phrase'),
('given that', '鑑於；考慮到', 'taking into account the fact that', '[{"en":"Given that resources are limited we must prioritize.","zh-TW":"鑑於資源有限我們必須排定優先順序。"},{"en":"Given that the deadline is close we need to act now.","zh-TW":"考慮到截止日期臨近我們需要立刻行動。"}]', 'prepositional phrase'),
('beyond the scope of', '超出…的範圍', 'outside the boundaries of what has been agreed or planned', '[{"en":"This request is beyond the scope of our contract.","zh-TW":"這個要求超出了我們合同的範圍。"},{"en":"The issue is beyond the scope of this meeting.","zh-TW":"這個問題超出了本次會議的範圍。"}]', 'prepositional phrase'),
('within the bounds of', '在…範圍之內；在…限制內', 'inside the limits that are allowed or reasonable', '[{"en":"All decisions must be within the bounds of the law.","zh-TW":"所有決定必須在法律範圍之內。"},{"en":"The team operates within the bounds of company policy.","zh-TW":"團隊在公司政策的範圍內運作。"}]', 'prepositional phrase'),
('from the ground up', '從頭開始；從零開始', 'starting completely from the beginning', '[{"en":"We built the system from the ground up.","zh-TW":"我們從零開始建立了這個系統。"},{"en":"The new platform was redesigned from the ground up.","zh-TW":"新平台從頭開始重新設計。"}]', 'prepositional phrase');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('above and beyond', '超出預期；額外付出', 'more than what is expected or required', '[{"en":"She went above and beyond in serving the client.","zh-TW":"她在服務客戶方面超越了期望。"},{"en":"The team went above and beyond to deliver on time.","zh-TW":"團隊額外付出以準時交付。"}]', 'prepositional phrase'),
('to the detriment of', '有損於；危害到', 'causing harm or damage to something or someone', '[{"en":"Shortcuts were taken to the detriment of quality.","zh-TW":"走捷徑有損於品質。"},{"en":"Speed was prioritized to the detriment of accuracy.","zh-TW":"速度被優先考慮而犧牲了準確性。"}]', 'prepositional phrase'),
('in conjunction', '聯合；同時；協同', 'together or at the same time as something else', '[{"en":"The two teams worked in conjunction on the launch.","zh-TW":"兩個團隊聯合推進了發布活動。"},{"en":"Marketing and sales should work in conjunction.","zh-TW":"行銷與銷售應協同工作。"}]', 'prepositional phrase'),
('the elephant in the room', '房間裡的大象；顯而易見卻被刻意忽略的問題', 'an obvious problem that people avoid discussing', '[{"en":"Let us address the elephant in the room — costs are too high.","zh-TW":"讓我們直面顯而易見的問題——成本太高了。"},{"en":"The elephant in the room is the lack of leadership.","zh-TW":"被刻意忽略的問題是領導力的缺乏。"}]', 'business idiom'),
('ballpark figure', '概略數字；大概估算', 'an approximate number or estimate', '[{"en":"Can you give me a ballpark figure for the project cost?","zh-TW":"你能給我一個專案費用的大概數字嗎？"},{"en":"A ballpark figure suggests the renovation will cost about 1 million.","zh-TW":"大概估算翻新費用約為一百萬。"}]', 'business idiom'),
('bread and butter', '主要收入來源；核心業務', 'the primary source of income or most important activity', '[{"en":"Software subscriptions are our bread and butter.","zh-TW":"軟體訂閱是我們的主要收入來源。"},{"en":"Repeat customers are the bread and butter of any business.","zh-TW":"回頭客是任何業務的核心。"}]', 'business idiom'),
('burning question', '迫切的問題；燃眉之急', 'an urgent or highly important question that needs answering', '[{"en":"The burning question is whether to expand overseas.","zh-TW":"迫切的問題是是否要拓展海外市場。"},{"en":"Investors have a burning question about profitability.","zh-TW":"投資者對盈利能力有一個迫切的問題。"}]', 'business idiom'),
('buzz word', '流行語；時髦術語', 'a fashionable term often used to sound current', '[{"en":"Innovation is a buzzword that needs concrete meaning.","zh-TW":"創新是一個需要具體含義的流行語。"},{"en":"Good reports avoid unnecessary buzzwords.","zh-TW":"好的報告避免使用不必要的流行語。"}]', 'business idiom'),
('cash cow', '搖錢樹；穩定盈利的業務', 'a product or business that consistently generates profit', '[{"en":"This product line has been our cash cow for a decade.","zh-TW":"這條產品線十年來一直是我們的搖錢樹。"},{"en":"Protecting the cash cow is essential for long-term stability.","zh-TW":"保護搖錢樹對長期穩定至關重要。"}]', 'business idiom'),
('on autopilot', '自動運行；按慣例行事', 'operating automatically without active thought or control', '[{"en":"The department has been running on autopilot for months.","zh-TW":"這個部門幾個月來一直在按慣例運作。"},{"en":"Innovation suffers when teams operate on autopilot.","zh-TW":"當團隊按慣例行事時創新就會受到影響。"}]', 'business idiom'),
('dead in the water', '毫無進展；陷入僵局', 'unable to move forward; completely stopped', '[{"en":"Without funding the project is dead in the water.","zh-TW":"沒有資金專案就毫無進展。"},{"en":"After the scandal the partnership was dead in the water.","zh-TW":"醜聞後這個合作關係陷入了僵局。"}]', 'business idiom'),
('dot the i''s and cross the t''s', '一絲不苟；注意所有細節', 'to pay careful attention to every detail', '[{"en":"Make sure to dot the i''s and cross the t''s before filing.","zh-TW":"提交前務必一絲不苟地核對每個細節。"},{"en":"She dotted every i and crossed every t in the contract.","zh-TW":"她仔細核對了合同中的每個細節。"}]', 'business idiom'),
('elevator pitch', '電梯提案；簡短有力的推介', 'a brief and persuasive speech about an idea or product', '[{"en":"He practiced his elevator pitch before the investor meeting.","zh-TW":"他在投資者會議前練習了他的電梯提案。"},{"en":"A good elevator pitch should last no more than 60 seconds.","zh-TW":"好的電梯提案應不超過60秒。"}]', 'business idiom'),
('fall flat', '失敗；反應冷淡', 'to fail to produce the intended effect or response', '[{"en":"The rebranding campaign fell flat with consumers.","zh-TW":"品牌重塑活動在消費者中反應冷淡。"},{"en":"His presentation fell flat without concrete data.","zh-TW":"他的簡報因缺乏具體數據而失敗了。"}]', 'business idiom'),
('fat cat', '大老闆；富豪', 'a powerful or wealthy person, especially in business', '[{"en":"The fat cats at the top received large bonuses.","zh-TW":"高層的大老闆們獲得了豐厚的獎金。"},{"en":"Workers resented the fat cat executives during layoffs.","zh-TW":"裁員期間員工對富豪高管們感到憤憤不平。"}]', 'business idiom'),
('feel the pinch', '感到拮据；受到財務壓力', 'to experience difficulty due to reduced money or resources', '[{"en":"Small businesses are feeling the pinch of rising costs.","zh-TW":"小企業正感受到成本上漲的財務壓力。"},{"en":"We are starting to feel the pinch from budget cuts.","zh-TW":"我們開始感受到預算削減的壓力。"}]', 'business idiom'),
('fire on all cylinders', '全力運轉；全速前進', 'working at maximum efficiency or capacity', '[{"en":"After the restructuring the team is firing on all cylinders.","zh-TW":"重組後團隊全力運轉。"},{"en":"The factory is firing on all cylinders this quarter.","zh-TW":"這個季度工廠在全速前進。"}]', 'business idiom'),
('flagship product', '旗艦產品；代表性產品', 'a company''s best or most important product', '[{"en":"The new smartphone is the company''s flagship product.","zh-TW":"新智慧型手機是公司的旗艦產品。"},{"en":"Flagship products should reflect brand values.","zh-TW":"旗艦產品應體現品牌價值觀。"}]', 'business idiom'),
('flying colors', '出色地；大獲全勝', 'with great success or distinction', '[{"en":"She passed the certification exam with flying colors.","zh-TW":"她以優異成績通過了認證考試。"},{"en":"The audit was completed with flying colors.","zh-TW":"審計以優異結果完成。"}]', 'business idiom'),
('action on', '對…採取行動；執行', 'to act on or implement a decision or request', '[{"en":"Please action on the client''s feedback by Friday.","zh-TW":"請在週五前對客戶的反饋採取行動。"},{"en":"We will action on the board''s recommendation immediately.","zh-TW":"我們將立即執行董事會的建議。"}]', 'phrasal verb'),
('check off', '勾除；完成並標記', 'to mark as completed on a list', '[{"en":"She checked off each task as it was completed.","zh-TW":"她完成每項任務後都勾除了它。"},{"en":"Before shipping, check off every item on the checklist.","zh-TW":"出貨前勾除清單上的每個項目。"}]', 'phrasal verb'),
('circle around', '圍繞；再次討論', 'to return to a topic or hover around an issue', '[{"en":"The discussion kept circling around the same problem.","zh-TW":"討論一直圍繞著同一個問題打轉。"},{"en":"Let us stop circling around and address the issue.","zh-TW":"讓我們停止繞圈子直接解決問題。"}]', 'phrasal verb'),
('delegate to', '授權給；委派給', 'to assign a task or responsibility to someone else', '[{"en":"Managers should delegate to their team members.","zh-TW":"管理者應將任務授權給團隊成員。"},{"en":"She delegated the research to junior staff.","zh-TW":"她將研究工作委派給了初級員工。"}]', 'phrasal verb'),
('expand on', '詳細說明；展開闡述', 'to provide more details or information about something', '[{"en":"Could you expand on your proposal?","zh-TW":"你能詳細說明你的提案嗎？"},{"en":"She expanded on the financial projections in the appendix.","zh-TW":"她在附錄中詳細說明了財務預測。"}]', 'phrasal verb'),
('finalize', '最終確定；完成定稿', 'to reach final agreement on or complete something', '[{"en":"We need to finalize the contract by end of week.","zh-TW":"我們需要在本週末前最終確定合同。"},{"en":"The team finalized the product specifications.","zh-TW":"團隊完成了產品規格的定稿。"}]', 'phrasal verb'),
('hold back', '阻礙；保留；克制', 'to restrain, withhold, or prevent progress', '[{"en":"Lack of funding is holding back our expansion.","zh-TW":"資金不足阻礙了我們的擴張。"},{"en":"She held back her comments until the end.","zh-TW":"她保留了評論直到最後。"}]', 'phrasal verb'),
('identify with', '認同；與…產生共鳴', 'to feel a strong connection or similarity with', '[{"en":"Customers who identify with our brand are loyal.","zh-TW":"認同我們品牌的客戶都是忠實客戶。"},{"en":"She identifies with the company''s sustainability mission.","zh-TW":"她與公司的永續發展使命產生共鳴。"}]', 'phrasal verb'),
('key in', '鍵入；輸入', 'to type data into a system', '[{"en":"Please key in your order number to check the status.","zh-TW":"請輸入您的訂單號查詢狀態。"},{"en":"She keyed in the client information to the database.","zh-TW":"她將客戶資訊鍵入了資料庫。"}]', 'phrasal verb'),
('level up', '提升；升級', 'to improve skills or advance to a higher level', '[{"en":"The training programme helped the team level up.","zh-TW":"培訓計劃幫助團隊提升了技能。"},{"en":"She leveled up her project management skills online.","zh-TW":"她通過線上課程提升了專案管理技能。"}]', 'phrasal verb'),
('network with', '與…建立人脈；社交', 'to make professional connections with others', '[{"en":"She networked with industry leaders at the conference.","zh-TW":"她在會議上與業界領袖建立了人脈。"},{"en":"Always take opportunities to network with peers.","zh-TW":"一定要把握機會與同行建立人脈。"}]', 'phrasal verb'),
('open to', '對…持開放態度；願意接受', 'willing to consider or receive something', '[{"en":"We are open to feedback from all departments.","zh-TW":"我們對所有部門的反饋持開放態度。"},{"en":"She is open to new approaches to the problem.","zh-TW":"她願意接受解決問題的新方法。"}]', 'phrasal verb'),
('pencil in', '暫定安排；預先填入（行程）', 'to make a tentative arrangement for something', '[{"en":"Let us pencil in Thursday for a review meeting.","zh-TW":"讓我們暫定週四開審查會議。"},{"en":"She penciled in the conference dates for next quarter.","zh-TW":"她將下個季度的會議日期暫定填入了行程。"}]', 'phrasal verb'),
('press ahead', '繼續前進；堅持推進', 'to continue despite difficulties or opposition', '[{"en":"We will press ahead with the launch as planned.","zh-TW":"我們將按計劃繼續推進發布活動。"},{"en":"She pressed ahead despite the budget freeze.","zh-TW":"她在預算凍結的情況下堅持推進。"}]', 'phrasal verb'),
('refer to', '參考；稱呼為；轉介', 'to mention, consult, or direct to a source', '[{"en":"Please refer to the attached guidelines.","zh-TW":"請參考附件中的指引。"},{"en":"She referred the client to our technical support team.","zh-TW":"她將客戶轉介給我們的技術支援團隊。"}]', 'phrasal verb'),
('report to', '向…匯報；向…負責', 'to be answerable to a manager or authority', '[{"en":"The sales team reports to the regional director.","zh-TW":"銷售團隊向區域總監匯報。"},{"en":"She will report directly to the CEO in the new role.","zh-TW":"在新職位上她將直接向執行長匯報。"}]', 'phrasal verb'),
('ring up', '打電話給；合計（金額）', 'to make a phone call, or to record a sale amount', '[{"en":"Ring up the supplier and confirm the delivery date.","zh-TW":"打電話給供應商確認送貨日期。"},{"en":"The cashier rang up the total at the counter.","zh-TW":"收銀員在櫃台計算了總金額。"}]', 'phrasal verb'),
('at face value', '按字面意思；不加懷疑地', 'accepting something at its apparent meaning without questioning', '[{"en":"Do not take the offer at face value — read the fine print.","zh-TW":"不要不加懷疑地接受報價——要仔細閱讀細則。"},{"en":"She accepted the report at face value without verification.","zh-TW":"她未加驗證就按字面接受了報告。"}]', 'expression'),
('ahead of the game', '領先一步；優於競爭對手', 'more advanced or prepared than others', '[{"en":"Early investment kept us ahead of the game.","zh-TW":"早期投資讓我們領先一步。"},{"en":"She stayed ahead of the game by attending industry events.","zh-TW":"她透過參加業界活動保持領先地位。"}]', 'expression'),
('bite the hand that feeds you', '恩將仇報；傷害支持者', 'to harm or act against those who support you', '[{"en":"Publicly criticizing your main client is biting the hand that feeds you.","zh-TW":"公開批評主要客戶是恩將仇報。"},{"en":"He bit the hand that fed him by leaking company secrets.","zh-TW":"他洩露公司機密是恩將仇報。"}]', 'expression'),
('chain of command', '指揮系統；層級體制', 'the hierarchy of authority through which orders are passed', '[{"en":"Always follow the chain of command when escalating issues.","zh-TW":"升級問題時一定要遵循指揮系統。"},{"en":"The chain of command was unclear during the transition.","zh-TW":"過渡期間指揮系統不清晰。"}]', 'expression'),
('cost-effective', '具有成本效益；划算', 'providing good value relative to cost', '[{"en":"Outsourcing is a cost-effective solution for small teams.","zh-TW":"外包對小型團隊來說是具有成本效益的解決方案。"},{"en":"We chose the most cost-effective supplier.","zh-TW":"我們選擇了最具成本效益的供應商。"}]', 'expression'),
('due diligence', '盡職調查；謹慎調查', 'the investigation of a business or investment before commitment', '[{"en":"We conducted thorough due diligence before the acquisition.","zh-TW":"我們在收購前進行了徹底的盡職調查。"},{"en":"Due diligence revealed several financial irregularities.","zh-TW":"盡職調查發現了幾處財務不規則事項。"}]', 'expression'),
('economies of scale', '規模經濟；大規模生產的成本優勢', 'cost advantages gained from increased production volume', '[{"en":"Larger companies benefit from economies of scale.","zh-TW":"較大的公司從規模經濟中受益。"},{"en":"To compete we must achieve economies of scale.","zh-TW":"為了競爭我們必須實現規模經濟。"}]', 'expression'),
('exit strategy', '退出策略', 'a plan for leaving a business or investment position', '[{"en":"Before investing consider your exit strategy.","zh-TW":"在投資前考慮好你的退出策略。"},{"en":"The founders had no exit strategy when the market shifted.","zh-TW":"市場轉變時創辦人沒有退出策略。"}]', 'expression'),
('first mover advantage', '先行者優勢', 'the benefit gained by being first in a market or industry', '[{"en":"We gained first mover advantage by launching early.","zh-TW":"我們透過早期推出獲得了先行者優勢。"},{"en":"First mover advantage is critical in technology markets.","zh-TW":"在技術市場先行者優勢至關重要。"}]', 'expression'),
('flat organizational structure', '扁平組織架構', 'a hierarchy with few management levels', '[{"en":"A flat organizational structure improves communication.","zh-TW":"扁平組織架構改善了溝通。"},{"en":"The startup adopted a flat structure from the beginning.","zh-TW":"這家新創公司從一開始就採用了扁平結構。"}]', 'expression'),
('have second thoughts', '再三考慮；猶豫', 'to reconsider a decision; to have doubts', '[{"en":"She had second thoughts about accepting the role.","zh-TW":"她對是否接受這個職位再三考慮。"},{"en":"The client had second thoughts after reviewing the contract.","zh-TW":"客戶審閱合同後產生了猶豫。"}]', 'expression'),
('hit the headlines', '成為頭條；引起廣泛關注', 'to receive prominent media coverage', '[{"en":"The product launch hit the headlines globally.","zh-TW":"產品發布成為全球頭條新聞。"},{"en":"The company hit the headlines after the data breach.","zh-TW":"數據洩露後公司成為了頭條新聞。"}]', 'expression'),
('level playing field', '公平競爭環境', 'a situation where everyone has an equal chance', '[{"en":"New regulations create a level playing field for all businesses.","zh-TW":"新法規為所有企業創造了公平競爭環境。"},{"en":"We advocate for a level playing field in the industry.","zh-TW":"我們倡導行業內的公平競爭環境。"}]', 'expression'),
('keep pace with', '跟上；跟上步伐', 'to move or develop at the same speed as', '[{"en":"It is challenging to keep pace with technology changes.","zh-TW":"跟上技術變革是一大挑戰。"},{"en":"We invest in training to keep pace with industry developments.","zh-TW":"我們投資培訓以跟上行業發展。"}]', 'expression');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('make a difference', '產生影響；有所作為', 'to have a significant effect or impact', '[{"en":"Good leadership makes a real difference to team morale.","zh-TW":"好的領導力對團隊士氣產生真正的影響。"},{"en":"We believe our product makes a difference to users'' lives.","zh-TW":"我們相信我們的產品對用戶的生活有所改變。"}]', 'expression'),
('no-brainer', '顯而易見的決定；不假思索的選擇', 'a decision or choice that is obviously correct', '[{"en":"With these savings it is a no-brainer to switch suppliers.","zh-TW":"有了這些節省換供應商是顯而易見的選擇。"},{"en":"Investing in training is a no-brainer.","zh-TW":"投資培訓是理所當然的選擇。"}]', 'expression'),
('once in a blue moon', '難得一見；偶爾', 'very rarely; only occasionally', '[{"en":"Opportunities like this come once in a blue moon.","zh-TW":"像這樣的機會難得一見。"},{"en":"We get a client like that once in a blue moon.","zh-TW":"我們難得遇到這樣的客戶。"}]', 'expression'),
('out of the question', '不可能；絕對不行', 'completely impossible or not permissible', '[{"en":"A budget increase is out of the question this year.","zh-TW":"今年增加預算絕對不可能。"},{"en":"Meeting that deadline is out of the question.","zh-TW":"趕上那個截止日期是不可能的。"}]', 'expression'),
('par excellence', '首屈一指；卓越的', 'better than all others of the same kind; supreme', '[{"en":"She is a communicator par excellence.","zh-TW":"她是首屈一指的溝通者。"},{"en":"This is innovation par excellence in the industry.","zh-TW":"這是業界卓越的創新典範。"}]', 'expression'),
('pick someone''s brain', '請教某人；請某人獻策', 'to ask someone for ideas or information based on their knowledge', '[{"en":"Can I pick your brain about the market strategy?","zh-TW":"我能請教你關於市場策略的想法嗎？"},{"en":"She picked his brain for insights on the Asian market.","zh-TW":"她請教他關於亞洲市場的見解。"}]', 'expression'),
('regardless of the circumstances', '不論情況如何', 'no matter what the situation may be', '[{"en":"Quality must be maintained regardless of the circumstances.","zh-TW":"不論情況如何品質都必須維持。"},{"en":"We deliver on time regardless of the circumstances.","zh-TW":"不論情況如何我們都準時交付。"}]', 'prepositional phrase'),
('in the short run', '短期而言；在短期內', 'over a brief time period; in the near future', '[{"en":"In the short run costs will rise after the change.","zh-TW":"短期而言變革後成本會上升。"},{"en":"These measures help in the short run but not long term.","zh-TW":"這些措施短期有效但長期不夠。"}]', 'prepositional phrase'),
('at a loss', '不知所措；虧損', 'uncertain what to do, or selling below cost', '[{"en":"After the failed pilot she was at a loss for next steps.","zh-TW":"試點失敗後她不知道下一步該怎麼辦。"},{"en":"We cannot afford to sell at a loss.","zh-TW":"我們不能虧本銷售。"}]', 'prepositional phrase'),
('to good effect', '有效地；達到良好效果', 'with a positive and noticeable result', '[{"en":"She used humor to good effect to ease the tension.","zh-TW":"她有效地運用幽默緩解了緊張氣氛。"},{"en":"The new software was deployed to good effect.","zh-TW":"新軟體被有效部署並達到了良好效果。"}]', 'prepositional phrase'),
('in a nutshell', '簡言之；簡而言之', 'in a brief and concise summary', '[{"en":"In a nutshell our strategy is to focus on quality.","zh-TW":"簡言之我們的策略是專注於品質。"},{"en":"Can you explain the issue in a nutshell?","zh-TW":"你能簡而言之地解釋一下這個問題嗎？"}]', 'prepositional phrase'),
('with the aim of', '以…為目的；旨在', 'with the purpose or intention of achieving something', '[{"en":"We are restructuring with the aim of improving efficiency.","zh-TW":"我們正在重組旨在提高效率。"},{"en":"With the aim of reducing costs we reviewed all contracts.","zh-TW":"以降低成本為目的我們審查了所有合同。"}]', 'prepositional phrase'),
('in terms of reference', '就職責範圍而言；依照職權範圍', 'within the boundaries of a defined scope or mandate', '[{"en":"The committee acts within its terms of reference.","zh-TW":"委員會在其職責範圍內行事。"},{"en":"This falls outside our terms of reference.","zh-TW":"這超出了我們的職責範圍。"}]', 'prepositional phrase'),
('in one''s capacity as', '以…的身份', 'in the role or position of a particular function', '[{"en":"In her capacity as CFO she approved the budget.","zh-TW":"以財務長的身份她批准了預算。"},{"en":"In his capacity as legal counsel he reviewed the contract.","zh-TW":"以法律顧問的身份他審查了合同。"}]', 'prepositional phrase'),
('as a token of', '作為…的表示；作為紀念', 'as a symbolic gesture expressing something', '[{"en":"As a token of appreciation we sent gifts to all clients.","zh-TW":"作為感謝的表示我們向所有客戶送了禮品。"},{"en":"The discount was offered as a token of goodwill.","zh-TW":"折扣是作為善意的表示提供的。"}]', 'prepositional phrase'),
('against all odds', '克服重重困難；不顧一切', 'despite very low chances of success', '[{"en":"Against all odds the startup became a market leader.","zh-TW":"克服重重困難這家新創公司成為了市場領導者。"},{"en":"She completed the project against all odds.","zh-TW":"她不顧一切完成了這個專案。"}]', 'prepositional phrase'),
('at the mercy of', '任由…擺布；受制於', 'entirely dependent on or vulnerable to something', '[{"en":"Small farmers are at the mercy of global price fluctuations.","zh-TW":"小農戶任由全球價格波動擺布。"},{"en":"Without a contract we are at the mercy of the supplier.","zh-TW":"沒有合同我們受制於供應商。"}]', 'prepositional phrase'),
('on equal terms', '在平等條件下；平起平坐', 'having the same position or conditions as others', '[{"en":"Smaller firms cannot always compete on equal terms.","zh-TW":"小公司不總是能在平等條件下競爭。"},{"en":"We want to negotiate on equal terms.","zh-TW":"我們希望在平等條件下進行談判。"}]', 'prepositional phrase'),
('in a timely manner', '及時地；迅速地', 'done at a suitable or efficient time', '[{"en":"All requests must be processed in a timely manner.","zh-TW":"所有請求都必須及時處理。"},{"en":"The team delivered results in a timely manner.","zh-TW":"團隊及時交付了結果。"}]', 'prepositional phrase'),
('with due respect', '恕我直言；請恕我冒昧', 'used politely before expressing disagreement', '[{"en":"With due respect I disagree with this assessment.","zh-TW":"恕我直言我不同意這個評估。"},{"en":"With due respect there are flaws in the proposal.","zh-TW":"恕我冒昧提案中存在缺陷。"}]', 'prepositional phrase'),
('at the bottom of', '在…的底部；是…的根本原因', 'the real or fundamental cause of something', '[{"en":"Poor planning is at the bottom of all these delays.","zh-TW":"規劃不當是所有這些延誤的根本原因。"},{"en":"What is really at the bottom of the conflict?","zh-TW":"這場衝突的真正根本原因是什麼？"}]', 'prepositional phrase'),
('to no avail', '徒勞無益；無濟於事', 'without success; making no difference', '[{"en":"We tried to contact them but to no avail.","zh-TW":"我們試圖聯繫他們但徒勞無益。"},{"en":"The marketing push drove traffic but to no avail on conversions.","zh-TW":"行銷推廣帶來了流量但在轉化方面無濟於事。"}]', 'prepositional phrase'),
('with immediate effect', '即時生效；立即執行', 'starting right away; with no delay', '[{"en":"The new policy takes effect with immediate effect.","zh-TW":"新政策即時生效。"},{"en":"His resignation was accepted with immediate effect.","zh-TW":"他的辭呈即時生效被接受。"}]', 'prepositional phrase'),
('from rags to riches', '白手起家；從一窮二白到富貴', 'going from poverty to wealth through hard work or luck', '[{"en":"The founder went from rags to riches in ten years.","zh-TW":"這位創辦人在十年內白手起家。"},{"en":"Her from rags to riches story inspires many entrepreneurs.","zh-TW":"她白手起家的故事激勵了許多創業者。"}]', 'business idiom'),
('get the big picture', '把握全局；了解整體情況', 'to understand the overall situation or main point', '[{"en":"To make good decisions you need to get the big picture.","zh-TW":"要做出好決策你需要把握全局。"},{"en":"She always gets the big picture before diving into details.","zh-TW":"她總是先把握全局再深入細節。"}]', 'business idiom'),
('go down the drain', '付諸東流；浪費', 'to be wasted or to go to waste', '[{"en":"Without follow-through all that effort went down the drain.","zh-TW":"沒有跟進所有的努力都付諸東流了。"},{"en":"The failed deal sent months of work down the drain.","zh-TW":"交易失敗讓幾個月的工作付諸東流。"}]', 'business idiom'),
('go from strength to strength', '蒸蒸日上；持續進步', 'to continue to improve or become more successful', '[{"en":"The company has gone from strength to strength since the pivot.","zh-TW":"自從轉型後公司蒸蒸日上。"},{"en":"She has gone from strength to strength in her career.","zh-TW":"她的職業生涯持續進步。"}]', 'business idiom'),
('high-octane', '高效能的；充滿活力的', 'very energetic, powerful, or intense', '[{"en":"Working in a startup is a high-octane experience.","zh-TW":"在新創公司工作是充滿活力的體驗。"},{"en":"The sales floor is a high-octane environment.","zh-TW":"銷售樓層是一個高效能的環境。"}]', 'business idiom'),
('move the goalposts', '改變標準；臨時更改要求', 'to change requirements or expectations after the fact', '[{"en":"Clients who keep moving the goalposts delay delivery.","zh-TW":"不斷改變要求的客戶會延誤交付。"},{"en":"Management moved the goalposts after we met the target.","zh-TW":"我們達成目標後管理層臨時更改了要求。"}]', 'business idiom'),
('new kid on the block', '新入場者；新的競爭者', 'a newcomer to a field or industry', '[{"en":"As the new kid on the block we had to prove ourselves.","zh-TW":"作為新入場者我們必須證明自己的實力。"},{"en":"The new startup is the new kid on the block disrupting the market.","zh-TW":"這家新創公司是顛覆市場的新入場者。"}]', 'business idiom'),
('over and above', '超出；不僅如此', 'in addition to or exceeding the standard amount or expectation', '[{"en":"She delivered results over and above what was asked.","zh-TW":"她交付的成果超出了要求。"},{"en":"The bonus was paid over and above the base salary.","zh-TW":"獎金是在基本薪資之外額外支付的。"}]', 'business idiom'),
('raise capital', '籌集資金', 'to gather funding for a business or project', '[{"en":"The founder traveled worldwide to raise capital.","zh-TW":"創辦人走遍全球籌集資金。"},{"en":"Raising capital requires a solid business plan.","zh-TW":"籌集資金需要有扎實的商業計劃。"}]', 'business idiom'),
('reinvent the wheel', '多此一舉；重複造車輪', 'to waste time creating something that already exists', '[{"en":"Use existing templates — there is no need to reinvent the wheel.","zh-TW":"使用現有範本——沒有必要重複造車輪。"},{"en":"They reinvented the wheel instead of adopting proven solutions.","zh-TW":"他們多此一舉而不採用成熟的解決方案。"}]', 'business idiom'),
('rule of thumb', '經驗法則', 'a practical general principle based on experience', '[{"en":"As a rule of thumb budget 10% for unexpected costs.","zh-TW":"根據經驗法則為意外費用預留10%的預算。"},{"en":"Our rule of thumb is to respond within 24 hours.","zh-TW":"我們的經驗法則是在24小時內回覆。"}]', 'business idiom'),
('run circles around', '遠勝於；輕而易舉地超越', 'to perform much better than someone else', '[{"en":"Our new system runs circles around the old one.","zh-TW":"我們的新系統遠勝於舊系統。"},{"en":"She runs circles around her peers in sales numbers.","zh-TW":"她在銷售數字上輕而易舉地超越了同儕。"}]', 'business idiom'),
('short-term gain', '短期收益', 'a benefit achieved quickly but possibly at the expense of future gain', '[{"en":"Do not sacrifice quality for short-term gain.","zh-TW":"不要為了短期收益而犧牲品質。"},{"en":"The short-term gain was not worth the long-term loss.","zh-TW":"短期收益不值得長期損失。"}]', 'business idiom'),
('silver lining', '塞翁失馬之福；壞事中的好處', 'a positive aspect of a difficult situation', '[{"en":"The silver lining is that we learned from the failure.","zh-TW":"壞事中的好處是我們從失敗中學到了東西。"},{"en":"She found a silver lining in every setback.","zh-TW":"她在每次挫折中都找到了塞翁失馬之福。"}]', 'business idiom'),
('stop the bleeding', '止損；阻止惡化', 'to prevent further losses or damage', '[{"en":"The first priority is to stop the bleeding on losses.","zh-TW":"首要任務是止損。"},{"en":"Cost controls were put in place to stop the bleeding.","zh-TW":"成本控制措施被實施以阻止虧損惡化。"}]', 'business idiom'),
('sustainable growth', '可持續增長', 'growth that can be maintained over time without depleting resources', '[{"en":"We focus on sustainable growth rather than rapid expansion.","zh-TW":"我們專注於可持續增長而非快速擴張。"},{"en":"Sustainable growth requires investment in quality and people.","zh-TW":"可持續增長需要在品質和人才上投資。"}]', 'business idiom'),
('take a rain check', '改天再說；暫時婉拒', 'to postpone an offer or invitation to a later time', '[{"en":"Can I take a rain check on the lunch? I have a conflict.","zh-TW":"我能改天再吃午餐嗎？我有衝突。"},{"en":"She took a rain check on the seminar for next month.","zh-TW":"她把研討會推到了下個月。"}]', 'business idiom'),
('talk the talk and walk the walk', '言行一致；說到做到', 'to back up words with actions', '[{"en":"Great leaders talk the talk and walk the walk.","zh-TW":"優秀的領導者言行一致。"},{"en":"If you promote innovation you must walk the walk.","zh-TW":"如果你倡導創新你必須說到做到。"}]', 'business idiom'),
('run with', '大力推進；採納並執行', 'to proceed enthusiastically with an idea or plan', '[{"en":"She ran with the concept and developed it into a product.","zh-TW":"她大力推進這個概念並將其發展成產品。"},{"en":"Once approved we ran with the project.","zh-TW":"獲批後我們全力推進這個專案。"}]', 'phrasal verb'),
('sell on', '說服；繼續銷售', 'to convince someone of the value of something', '[{"en":"He sold the board on the new direction.","zh-TW":"他說服董事會接受了新方向。"},{"en":"Can you sell the client on upgrading their plan?","zh-TW":"你能說服客戶升級他們的方案嗎？"}]', 'phrasal verb'),
('settle on', '決定；選定', 'to choose or make a final decision about something', '[{"en":"We finally settled on a design after weeks of review.","zh-TW":"幾週審查後我們終於選定了一個設計。"},{"en":"Have you settled on a vendor yet?","zh-TW":"你決定好供應商了嗎？"}]', 'phrasal verb'),
('sign on', '簽約加入；同意合作', 'to commit formally to a job or project', '[{"en":"Three new sponsors signed on for the event.","zh-TW":"三個新贊助商簽約參加了這次活動。"},{"en":"She signed on as a consultant for the project.","zh-TW":"她以顧問身份簽約加入了專案。"}]', 'phrasal verb'),
('snap up', '搶購；迅速把握機會', 'to buy or take something quickly before others can', '[{"en":"Investors snapped up shares at the lower price.","zh-TW":"投資者以較低價格搶購了股票。"},{"en":"The company snapped up top talent from competitors.","zh-TW":"公司從競爭對手那裡搶到了頂尖人才。"}]', 'phrasal verb'),
('square away', '處理好；安排妥當', 'to settle or organize something completely', '[{"en":"Let me square away the remaining details.","zh-TW":"讓我把剩餘的細節都處理好。"},{"en":"Once logistics are squared away we can proceed.","zh-TW":"物流安排妥當後我們就可以繼續了。"}]', 'phrasal verb'),
('steer toward', '引導朝向；轉向', 'to guide or direct toward a particular direction', '[{"en":"She steered the company toward digital transformation.","zh-TW":"她引導公司走向數位轉型。"},{"en":"He steered the team toward a more innovative approach.","zh-TW":"他引導團隊朝向更具創新性的方式發展。"}]', 'phrasal verb'),
('supply with', '供應；提供給', 'to provide with goods or materials', '[{"en":"We supply the factory with raw materials monthly.","zh-TW":"我們每月向工廠提供原材料。"},{"en":"The vendor supplied us with high-quality components.","zh-TW":"供應商為我們提供了高品質零件。"}]', 'phrasal verb'),
('sustain with', '維持；以…支撐', 'to maintain or keep alive with resources or support', '[{"en":"We sustain operations with strong cash flow.","zh-TW":"我們以強健的現金流維持運作。"},{"en":"Innovation sustains the business through changes.","zh-TW":"創新使業務在變化中得以維持。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('switch over', '切換；轉換到', 'to change from one system or activity to another', '[{"en":"We switched over to the cloud-based system last year.","zh-TW":"我們去年切換到了雲端系統。"},{"en":"It takes time to switch over from the old process.","zh-TW":"從舊流程轉換需要時間。"}]', 'phrasal verb'),
('target toward', '針對；以…為目標', 'to aim an effort or product at a specific group or goal', '[{"en":"The campaign is targeted toward young professionals.","zh-TW":"這次活動針對年輕專業人士。"},{"en":"We target our services toward mid-size enterprises.","zh-TW":"我們的服務以中型企業為目標。"}]', 'phrasal verb'),
('think ahead', '預先考慮；未雨綢繆', 'to consider future needs or plan in advance', '[{"en":"We need to think ahead and anticipate market shifts.","zh-TW":"我們需要預先考慮並預測市場轉變。"},{"en":"Good leaders always think ahead.","zh-TW":"好的領導者總是未雨綢繆。"}]', 'phrasal verb'),
('transition to', '過渡到；轉型至', 'to move gradually from one state or role to another', '[{"en":"She transitioned to a management position this year.","zh-TW":"她今年過渡到了管理職位。"},{"en":"The company is transitioning to a subscription model.","zh-TW":"公司正在轉型至訂閱模式。"}]', 'phrasal verb'),
('turn to', '求助於；轉向', 'to go to someone for help or to change to an alternative', '[{"en":"When issues arise she turns to her mentor.","zh-TW":"當出現問題時她向導師求助。"},{"en":"The company turned to outsourcing to reduce costs.","zh-TW":"公司轉向外包以降低成本。"}]', 'phrasal verb'),
('update on', '更新；告知最新情況', 'to provide the latest information about something', '[{"en":"Please update me on the project status.","zh-TW":"請告知我專案的最新狀態。"},{"en":"She updated the team on the client''s requirements.","zh-TW":"她向團隊通報了客戶的最新需求。"}]', 'phrasal verb'),
('veer away from', '偏離；避開', 'to change direction away from something', '[{"en":"The discussion veered away from the agenda.","zh-TW":"討論偏離了議程。"},{"en":"She veered away from the risky option.","zh-TW":"她避開了風險較高的選項。"}]', 'phrasal verb'),
('validate against', '與…進行驗證；核對', 'to confirm accuracy by checking against a standard', '[{"en":"Please validate the figures against the source data.","zh-TW":"請將數字與源數據進行核對。"},{"en":"All results are validated against industry benchmarks.","zh-TW":"所有結果都與行業基準進行了驗證。"}]', 'phrasal verb'),
('walk through', '逐步說明；引導完成', 'to guide someone through a process step by step', '[{"en":"Let me walk you through the onboarding process.","zh-TW":"讓我逐步引導你完成入職流程。"},{"en":"She walked the client through the platform features.","zh-TW":"她逐步向客戶介紹了平台功能。"}]', 'phrasal verb'),
('yield to', '讓步；服從', 'to submit to pressure or give way to a superior force', '[{"en":"The company yielded to public pressure and revised the policy.","zh-TW":"公司在公眾壓力下讓步並修訂了政策。"},{"en":"She did not yield to the client''s unreasonable demands.","zh-TW":"她沒有屈服於客戶不合理的要求。"}]', 'phrasal verb'),
('put your best foot forward', '全力以赴；展現最佳狀態', 'to try as hard as possible to make a good impression', '[{"en":"Always put your best foot forward when meeting new clients.","zh-TW":"見新客戶時一定要全力以赴展現最佳狀態。"},{"en":"She put her best foot forward in the job interview.","zh-TW":"她在求職面試中展現了最佳狀態。"}]', 'expression'),
('put something into perspective', '以正確角度看待；客觀地評估', 'to consider something in a realistic way relative to other factors', '[{"en":"To put things into perspective our growth is still above average.","zh-TW":"以正確角度看待我們的增長仍高於平均水準。"},{"en":"She put the setback into perspective and moved forward.","zh-TW":"她客觀評估了挫折並繼續前進。"}]', 'expression'),
('raise the stakes', '提高賭注；加大風險或報酬', 'to increase the risks, importance, or rewards involved', '[{"en":"The acquisition raised the stakes for all competitors.","zh-TW":"這次收購提高了所有競爭者的賭注。"},{"en":"She raised the stakes by proposing a bolder strategy.","zh-TW":"她提出更大膽的策略提高了賭注。"}]', 'expression'),
('read the room', '察言觀色；感受現場氣氛', 'to assess the mood or expectations of others in a situation', '[{"en":"A good presenter reads the room and adjusts accordingly.","zh-TW":"優秀的演講者能察言觀色並相應調整。"},{"en":"He failed to read the room and misjudged the tone.","zh-TW":"他未能察言觀色並誤判了氣氛。"}]', 'expression'),
('rock the boat', '惹是生非；打破現狀', 'to cause trouble or upset a stable situation', '[{"en":"He was afraid to rock the boat by suggesting changes.","zh-TW":"他害怕提出改變建議而惹是生非。"},{"en":"Sometimes you need to rock the boat to drive improvement.","zh-TW":"有時你需要打破現狀來推動改進。"}]', 'expression'),
('smooth sailing', '一帆風順；順利進行', 'a situation where things proceed without difficulty', '[{"en":"After the initial phase it was smooth sailing.","zh-TW":"初期階段後一切一帆風順。"},{"en":"Getting the first client was tough but smooth sailing after that.","zh-TW":"獲得第一個客戶很艱難但之後就一帆風順了。"}]', 'expression'),
('step up to the plate', '挺身而出；承擔責任', 'to take on responsibility or rise to a challenge', '[{"en":"The team stepped up to the plate during the crisis.","zh-TW":"危機期間團隊挺身而出。"},{"en":"She stepped up to the plate when no one else would.","zh-TW":"她在沒有人願意的情況下挺身而出。"}]', 'expression'),
('swim against the tide', '逆流而上；反潮流', 'to go against the majority opinion or trend', '[{"en":"The brand swims against the tide by focusing on traditional methods.","zh-TW":"這個品牌通過專注於傳統方法逆流而上。"},{"en":"She swam against the tide and predicted the market correctly.","zh-TW":"她逆潮流而上並準確預測了市場走向。"}]', 'expression'),
('take it one step at a time', '一步一步來；循序漸進', 'to deal with things gradually and without rushing', '[{"en":"With such a complex project we should take it one step at a time.","zh-TW":"面對如此複雜的專案我們應該一步一步來。"},{"en":"Take it one step at a time and do not get overwhelmed.","zh-TW":"循序漸進不要因此感到不知所措。"}]', 'expression'),
('the writing is on the wall', '大難將至；徵兆已現', 'signs that something bad is about to happen are obvious', '[{"en":"The writing was on the wall when revenues fell three quarters in a row.","zh-TW":"連續三個季度收入下降時徵兆已現。"},{"en":"Many employees saw the writing on the wall before the layoffs.","zh-TW":"許多員工在裁員前就看到了大難將至的跡象。"}]', 'expression'),
('throw money at the problem', '砸錢解決問題；用金錢代替策略', 'to try to resolve a problem by spending money rather than fixing the cause', '[{"en":"You cannot just throw money at this problem — you need a strategy.","zh-TW":"你不能只是砸錢解決問題——你需要一個策略。"},{"en":"They threw money at the issue without diagnosing the root cause.","zh-TW":"他們未診斷根本原因就砸錢試圖解決問題。"}]', 'expression'),
('tread carefully', '謹慎行事；小心翼翼', 'to proceed with great caution', '[{"en":"Tread carefully when discussing sensitive topics with clients.","zh-TW":"與客戶討論敏感話題時要謹慎行事。"},{"en":"She tread carefully when delivering bad news.","zh-TW":"她在傳達壞消息時小心翼翼。"}]', 'expression'),
('turn a blind eye', '視而不見；裝作不知道', 'to deliberately ignore something problematic', '[{"en":"Management turned a blind eye to the compliance issues.","zh-TW":"管理層對合規問題視而不見。"},{"en":"Do not turn a blind eye to workplace misconduct.","zh-TW":"不要對職場不當行為裝作不知道。"}]', 'expression'),
('two sides of the same coin', '一體兩面；相互關聯的兩個方面', 'two things that seem different but are closely related', '[{"en":"Risk and opportunity are two sides of the same coin.","zh-TW":"風險和機會是一體兩面。"},{"en":"Customer satisfaction and profitability are two sides of the same coin.","zh-TW":"客戶滿意度和盈利能力是一體兩面。"}]', 'expression'),
('up the ante', '提高賭注；加大投入', 'to increase the stakes or demands in a situation', '[{"en":"The competitor upped the ante with aggressive pricing.","zh-TW":"競爭對手以積極的定價提高了賭注。"},{"en":"She upped the ante by proposing a 20% cost reduction.","zh-TW":"她提出20%成本降低要求加大了籌碼。"}]', 'expression'),
('fall on deaf ears', '充耳不聞；被忽視', 'to be heard but ignored or have no effect', '[{"en":"His concerns about quality fell on deaf ears.","zh-TW":"他對品質的擔憂充耳不聞。"},{"en":"The team''s suggestions fell on deaf ears.","zh-TW":"團隊的建議被忽視了。"}]', 'expression'),
('get your ducks in a row', '做好充分準備；安排妥當', 'to organize things properly before taking action', '[{"en":"Before the meeting get your ducks in a row.","zh-TW":"會議前做好充分準備。"},{"en":"We need to get our ducks in a row before the product launch.","zh-TW":"在產品發布前我們需要安排妥當。"}]', 'expression'),
('have the upper hand', '佔上風；處於優勢', 'to be in a position of advantage over others', '[{"en":"With better data we had the upper hand in the negotiation.","zh-TW":"有了更好的數據我們在談判中佔了上風。"},{"en":"Early movers have the upper hand in new markets.","zh-TW":"早期進入者在新市場中處於優勢地位。"}]', 'expression'),
('hit the spot', '正合心意；完全符合需求', 'to be exactly right or to satisfy a need perfectly', '[{"en":"That solution really hit the spot for the client.","zh-TW":"那個解決方案完全符合客戶的需求。"},{"en":"The new design hits the spot in terms of user experience.","zh-TW":"新設計在用戶體驗方面完全符合需求。"}]', 'expression'),
('lay the groundwork', '奠定基礎；打下基礎', 'to do the preparatory work for something in the future', '[{"en":"The pilot programme laid the groundwork for full rollout.","zh-TW":"試點計劃為全面推出奠定了基礎。"},{"en":"She spent months laying the groundwork for the merger.","zh-TW":"她花了幾個月為合併打下基礎。"}]', 'expression'),
('in the event that', '萬一；如果發生的話', 'if a particular situation should happen', '[{"en":"In the event that the delivery is late please inform us.","zh-TW":"萬一送貨延誤請告知我們。"},{"en":"In the event that the merger fails we have a backup plan.","zh-TW":"如果合併失敗我們有備選計劃。"}]', 'prepositional phrase'),
('pending approval', '待批准；等待批准', 'waiting for official authorization', '[{"en":"The project is on hold pending approval.","zh-TW":"專案暫停等待批准。"},{"en":"Pending approval from the board we can begin.","zh-TW":"等待董事會批准後我們即可開始。"}]', 'prepositional phrase'),
('under the auspices of', '在…的主持下；由…贊助', 'with the support or sponsorship of an organization', '[{"en":"The conference was held under the auspices of the UN.","zh-TW":"會議在聯合國的主持下舉行。"},{"en":"The project operates under the auspices of the government.","zh-TW":"該項目在政府的主持下運作。"}]', 'prepositional phrase'),
('with a grain of salt', '保留懷疑態度；半信半疑地', 'with some skepticism or caution', '[{"en":"Take the competitor''s claims with a grain of salt.","zh-TW":"對競爭對手的聲明要保留懷疑態度。"},{"en":"Initial sales projections should be taken with a grain of salt.","zh-TW":"初步銷售預測應該半信半疑。"}]', 'prepositional phrase'),
('off the top of one''s head', '不假思索地；憑印象', 'from memory without careful thought or research', '[{"en":"Off the top of my head I would estimate 50 units.","zh-TW":"憑我的印象我估計是50個單位。"},{"en":"She answered off the top of her head in the meeting.","zh-TW":"她在會議中不假思索地回答了問題。"}]', 'prepositional phrase'),
('on the premise that', '以…為前提；假設', 'based on the assumption that something is true', '[{"en":"On the premise that demand grows we are expanding.","zh-TW":"以需求增長為前提我們正在擴張。"},{"en":"We planned on the premise that budgets would not be cut.","zh-TW":"我們以預算不會被削減為前提進行規劃。"}]', 'prepositional phrase'),
('in the pipeline for', '即將推出；在籌備中', 'being prepared or planned for future release', '[{"en":"We have several updates in the pipeline for next quarter.","zh-TW":"我們有幾個更新正在籌備中將於下季度推出。"},{"en":"New features are in the pipeline for the platform.","zh-TW":"新功能正在為平台籌備中。"}]', 'prepositional phrase'),
('at the helm of', '掌舵；領導', 'in control of or leading an organization or team', '[{"en":"She has been at the helm of the company for six years.","zh-TW":"她已掌舵公司六年了。"},{"en":"With an experienced CEO at the helm the company thrived.","zh-TW":"在有經驗的執行長掌舵下公司蓬勃發展。"}]', 'prepositional phrase'),
('by mutual agreement', '經雙方同意；互相協議', 'with the consent of all involved parties', '[{"en":"The contract was terminated by mutual agreement.","zh-TW":"合同經雙方同意終止了。"},{"en":"By mutual agreement the meeting was rescheduled.","zh-TW":"經雙方同意會議重新安排了時間。"}]', 'prepositional phrase'),
('at the behest of', '在…的要求下；奉…之命', 'at the instruction or request of someone in authority', '[{"en":"At the behest of the board the audit was launched.","zh-TW":"在董事會的要求下審計啟動了。"},{"en":"At the behest of the client we revised the proposal.","zh-TW":"奉客戶之命我們修改了提案。"}]', 'prepositional phrase'),
('to the letter', '嚴格按照；一字不差地', 'following instructions or rules exactly and precisely', '[{"en":"We follow the safety protocol to the letter.","zh-TW":"我們嚴格按照安全規程執行。"},{"en":"The contract must be executed to the letter.","zh-TW":"合同必須一字不差地執行。"}]', 'prepositional phrase'),
('in pursuit of excellence', '追求卓越', 'in the effort to achieve the highest possible standards', '[{"en":"In pursuit of excellence we never stop improving.","zh-TW":"在追求卓越的過程中我們永不停止改進。"},{"en":"The team operates in pursuit of excellence in every project.","zh-TW":"團隊在每個專案中都追求卓越。"}]', 'prepositional phrase'),
('on a case-by-case basis', '逐案處理；按具體情況', 'dealing with each situation individually as it arises', '[{"en":"Exceptions will be handled on a case-by-case basis.","zh-TW":"例外情況將逐案處理。"},{"en":"Pricing is negotiated on a case-by-case basis.","zh-TW":"定價按具體情況協商。"}]', 'prepositional phrase'),
('in an advisory capacity', '以顧問身份', 'in a role providing guidance without decision-making power', '[{"en":"She joined the board in an advisory capacity.","zh-TW":"她以顧問身份加入了董事會。"},{"en":"The expert served in an advisory capacity throughout the project.","zh-TW":"專家在整個專案中以顧問身份提供服務。"}]', 'prepositional phrase'),
('in preparation for', '為…做準備；準備期間', 'in readiness or anticipation of something', '[{"en":"We held workshops in preparation for the product launch.","zh-TW":"我們舉辦了研討會為產品發布做準備。"},{"en":"In preparation for the audit all records were organized.","zh-TW":"為審計做準備所有記錄都整理好了。"}]', 'prepositional phrase'),
('on the strength of the results', '憑借結果；依據成效', 'justified or supported by the performance achieved', '[{"en":"On the strength of the results we received more funding.","zh-TW":"憑借成效我們獲得了更多資金。"},{"en":"Further contracts were awarded on the strength of the results.","zh-TW":"依據成效我們獲得了進一步的合同。"}]', 'prepositional phrase'),
('commensurate with', '與…相稱；成比例的', 'proportionate or matching in size, quality, or value', '[{"en":"Compensation is commensurate with experience and skills.","zh-TW":"薪酬與經驗和技能相稱。"},{"en":"The role offers rewards commensurate with performance.","zh-TW":"該職位提供與績效相稱的獎酬。"}]', 'prepositional phrase'),
('throughout the duration of', '在整個期間；持續整個過程', 'during the entire length of time something takes', '[{"en":"Quality must be maintained throughout the duration of the contract.","zh-TW":"在整個合同期間必須保持品質。"},{"en":"She supported the team throughout the duration of the change.","zh-TW":"她在整個變革過程中支持了團隊。"}]', 'prepositional phrase'),
('net of', '扣除…後的淨額；不含', 'after deducting or excluding something', '[{"en":"Net of taxes the profit was quite healthy.","zh-TW":"扣除稅款後利潤相當健康。"},{"en":"Please report revenue net of refunds.","zh-TW":"請報告扣除退款後的淨收入。"}]', 'prepositional phrase'),
('a tall order', '難以完成的任務；要求過高', 'a demand or requirement that is difficult to achieve', '[{"en":"Completing the project in one week is a tall order.","zh-TW":"在一週內完成這個專案是難以實現的任務。"},{"en":"Satisfying every stakeholder is always a tall order.","zh-TW":"滿足每位利益相關者總是難以實現的要求。"}]', 'business idiom');